const main=document.getElementById('main');let products=[],filter='Tous',search='';
const categories=['Légumes Frais','Légumes-feuilles & produits traditionnels','Fruits frais','Poissons & produits halieutiques','Produits agricoles et naturels','Viandes, volailles et œufs'];
const labels=['Légumes frais','Feuilles & traditions','Fruits frais','Poissons & crevettes','Produits agricoles','Viandes & œufs'];
const wa='https://wa.me/243834691077';
const services=[['Approvisionnement en produits frais','Nous sélectionnons les produits auprès d’agriculteurs, de producteurs locaux et de partenaires de confiance pour faciliter un approvisionnement régulier.'],['Vente et livraison','Un parcours de commande simple pour les ménages et les entreprises. Échangez avec notre équipe pour convenir des produits et de la livraison.'],['Paniers frais pour les ménages','Des paniers adaptés aux besoins quotidiens des familles. Composez votre sélection et échangez avec nous sur les produits disponibles.'],['Approvisionnement des entreprises','Nous accompagnons les restaurants, hôtels, entreprises et institutions dans leurs besoins réguliers en produits frais.'],['Collecte, logistique et distribution','Nous relions les lieux de production aux points de consommation grâce à la collecte, au transport et à la distribution des produits.'],['Accès aux marchés pour les producteurs','Nous aidons les producteurs et coopératives à commercialiser leurs produits et à accéder à de nouveaux débouchés.']];
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function card(p){let i=products.indexOf(p);return `<article class="product"><button class="product-img" data-product="${i}" aria-label="Voir ${escape(p.name)}"><img src="${p.image}" alt="${escape(p.name)}" loading="lazy"></button><div class="product-body"><small>${labels[categories.indexOf(p.category)]||p.category}</small><h3>${escape(p.name)}</h3><button class="more" data-product="${i}">Découvrir le produit <span>↗</span></button></div></article>`}
function cta(){return `<div class="container cta"><div><h2>Votre prochain panier<br>commence ici.</h2><p>Un besoin particulier ? Échangeons pour composer votre sélection.</p></div><button class="btn" data-chat>Discuter sur WhatsApp ↗</button></div>`}
function home(){return `<div class="container hero"><div><div class="eyebrow">MDS · Le lien qui fait la différence</div><h1>Le meilleur<br>du frais,<br><em>près de vous.</em></h1><p>Des produits frais pour chaque foyer. Nous connectons les producteurs, les commerçants et les consommateurs, du champ à votre table.</p><div class="actions"><a class="btn" href="#/produits">Explorer nos produits ↗</a><a class="btn light" href="#/services">Nos services →</a></div><div class="hero-note"><span>✧ Produits soigneusement sélectionnés</span><span>◎ Pour les familles et les professionnels</span></div></div><div class="hero-visual"><img src="assets/hero.jpg" alt="Des producteurs récoltant des légumes frais au champ"><div class="stamp">NATURELLEMENT<br><b>FRAIS</b><span>✦</span></div><div class="photo-badge"><span>❧</span><div><b>Du producteur à votre table</b><small>Une connexion qui crée de la valeur.</small></div></div></div></div><div class="ribbon"><span><b>❧</b> Fruits & légumes</span><span><b>≈</b> Poissons & produits frais</span><span><b>↗</b> Livraison & distribution</span><span><b>◎</b> Producteurs & entreprises</span></div><section class="block container"><div class="section-head"><div><div class="eyebrow">Notre univers</div><h2>Le goût du choix.</h2><p>Découvrez les essentiels pour votre cuisine et votre quotidien.</p></div><a class="text-link" href="#/produits">Tout le catalogue ↗</a></div><div class="categories">${categories.map((c,i)=>{const p=products.find(p=>p.category===c);return `<a class="category" href="#/produits?categorie=${i}"><img src="${p?.image||'assets/hero.jpg'}" alt="${labels[i]}" loading="lazy"><div><div style="position:static;display:block"><small>LA SÉLECTION MDS</small><h3>${labels[i]}</h3></div><i>↗</i></div></a>`}).join('')}</div></section><section class="block white"><div class="container"><div class="section-head"><div><div class="eyebrow">À découvrir</div><h2>Des essentiels, <em>tout simplement.</em></h2></div><a class="text-link" href="#/produits">Voir tous les produits ↗</a></div><div class="grid">${[1,14,24,30].map(i=>products[i]).filter(Boolean).map(card).join('')}</div></div></section><section class="block container split"><img src="assets/farm.jpg" alt="L’agriculture et les producteurs au cœur de notre mission" loading="lazy"><div><div class="eyebrow">Au-delà des produits</div><h2>Relier les hommes.<br><em>Faire grandir la valeur.</em></h2><p>MDS est une entreprise d’agribusiness qui contribue à moderniser et à valoriser les chaînes de valeur agricoles en Afrique.</p><p>Nous connectons producteurs, entreprises et consommateurs grâce à l’approvisionnement, la logistique, la distribution et le commerce numérique.</p><a class="text-link" href="#/a-propos">Découvrir MDS ↗</a></div></section><section class="block container"><div class="section-head"><div><div class="eyebrow">Comment ça marche</div><h2>Le frais en trois étapes.</h2></div></div><div class="steps"><div class="step"><span>01</span><h3>Explorez notre sélection</h3><p>Parcourez les catégories et découvrez les produits qui vous intéressent.</p></div><div class="step"><span>02</span><h3>Parlons de vos besoins</h3><p>Envoyez votre sélection à notre équipe sur WhatsApp et confirmez les disponibilités.</p></div><div class="step"><span>03</span><h3>Convenez de la livraison</h3><p>Notre équipe vous accompagne pour organiser votre commande et sa livraison.</p></div></div></section>${cta()}`}
function head(k,t,d){return `<div class="page-head container"><div class="eyebrow">${k}</div><h1>${t}</h1><p>${d}</p></div>`}
function catalog(){return head('Le catalogue MDS','Le frais sous toutes ses formes.','Des produits pour les repas du quotidien et les besoins des professionnels. Contactez-nous pour connaître les disponibilités.')+`<section class="container block" style="padding-top:20px"><div class="tools"><span class="result-count" id="count"></span><input class="search" id="search" aria-label="Rechercher un produit" placeholder="Rechercher un produit…" value="${escape(search)}"></div><div class="filters"><button data-filter="Tous">Tout voir</button>${categories.map((c,i)=>`<button data-filter="${escape(c)}">${labels[i]}</button>`).join('')}</div><div class="grid" id="catalog-grid"></div></section>`+cta()}
function updateCatalog(){const q=search.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const found=products.filter(p=>(filter==='Tous'||p.category===filter)&&p.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(q));document.getElementById('catalog-grid').innerHTML=found.length?found.map(card).join(''):'<div class="empty"><h3>Aucun produit trouvé</h3><p>Essayez un autre nom ou une autre catégorie.</p><button class="btn light" id="reset-search">Afficher tous les produits</button></div>';document.getElementById('count').textContent=`${found.length} produit${found.length>1?'s':''} à découvrir`;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.filter===filter))}
function about(){return head('À propos de MDS','Cultiver les connexions.','Une entreprise d’agribusiness tournée vers les producteurs, les entreprises et les foyers.')+`<section class="container block split" style="padding-top:20px"><img src="assets/farm.jpg" alt="Agriculture et produits frais"><div><div class="eyebrow">Qui sommes-nous ?</div><h2>Une chaîne de valeur.<br>Des liens <em>essentiels.</em></h2><p>MDS contribue à moderniser et à valoriser les chaînes de valeur agricoles en Afrique. Nous relions les producteurs, les entreprises et les consommateurs grâce à des solutions d’approvisionnement, de logistique, de distribution et de commerce numérique.</p><p>Notre ambition : faciliter l’accès aux produits frais, naturels et de qualité, tout en créant des opportunités économiques pour les communautés.</p></div></section><section class="container block services"><article class="service"><span>01 — Notre vision</span><h3>Plus de valeur, plus d’opportunités.</h3><p>Permettre aux communautés africaines de créer davantage de valeur en connectant les producteurs aux marchés et en facilitant l’accès de chaque foyer à des produits frais grâce à l’innovation et à la logistique.</p></article><article class="service"><span>02 — Notre mission</span><h3>Rapprocher le champ et la table.</h3><p>Faciliter la connexion entre les agriculteurs, les producteurs, les entreprises locales et les consommateurs grâce à des chaînes d’approvisionnement fiables, à la technologie et au commerce numérique.</p></article></section>`+cta()}
function servicePage(){return head('Les services MDS','À chaque besoin, une connexion.','De l’approvisionnement à la distribution, nous accompagnons les foyers, les entreprises et les producteurs.')+`<section class="container block services" style="padding-top:20px">${services.map((s,i)=>`<article class="service"><span>0${i+1}</span><h3>${s[0]}</h3><p>${s[1]}</p><button class="text-link" style="border:0;border-bottom:1px solid;background:none;color:inherit;padding-left:0" data-request="${s[0]}">Parlons de ce service ↗</button></article>`).join('')}</section>`+cta()}
function contact(){return head('Contact','Une question ? Parlons-en.','Une commande, un devis ou un projet d’approvisionnement : nous sommes à votre écoute.')+`<div class="container contact-layout"><div class="contact-card"><h3>Retrouvez MDS à Kinshasa.</h3><p>9 A, Avenue Massamba<br>Quartier Basoko, Commune de Ngaliema<br>Kinshasa, République démocratique du Congo</p><hr><h3>Le contact en toute simplicité.</h3><p>Préparez votre message et échangez directement avec notre équipe sur WhatsApp.</p><button class="btn" data-chat>Ouvrir l’assistant ↗</button><hr><a class="text-link" href="https://www.facebook.com/profile.php?id=61576429634122" target="_blank" rel="noopener">Facebook ↗</a> &nbsp; <a class="text-link" href="https://www.linkedin.com/company/microlog-delivery-services" target="_blank" rel="noopener">LinkedIn ↗</a></div><form class="contact-form" id="contact-form"><label for="name">Votre nom *</label><input id="name" name="name" required autocomplete="name" placeholder="Comment vous appelez-vous ?"><label for="email">Votre adresse e-mail</label><input id="email" name="email" type="email" autocomplete="email" placeholder="vous@exemple.com"><label for="message">Votre demande *</label><textarea id="message" name="message" required placeholder="Les produits souhaités, les quantités ou votre besoin…"></textarea><button class="btn" type="submit">Préparer ma demande WhatsApp ↗</button><small>Votre demande s’ouvre dans WhatsApp. Vous pourrez la vérifier avant de l’envoyer.</small><p id="contact-status" role="status"></p></form></div>`}
function route(){const raw=location.hash.slice(1)||'/';const [path,query]=raw.split('?');if(path==='/produits'){const n=new URLSearchParams(query).get('categorie');filter=n!==null?categories[Number(n)]||'Tous':'Tous';search='';main.innerHTML=catalog();updateCatalog()}else if(path==='/services')main.innerHTML=servicePage();else if(path==='/a-propos')main.innerHTML=about();else if(path==='/contact')main.innerHTML=contact();else main.innerHTML=home();document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+path));document.querySelector('nav').classList.remove('open');document.getElementById('menu').setAttribute('aria-expanded','false');document.title=({ '/produits':'Nos produits','/services':'Services','/a-propos':'À propos','/contact':'Contact'}[path]||'Le frais, tout simplement.')+' — MDS';window.scrollTo(0,0)}
function setRequest(text){document.getElementById('whatsapp').href=wa+'?text='+encodeURIComponent(text)}
function openChat(text){document.getElementById('chat').hidden=false;if(text){addBubble(text,true);setRequest(text)}document.getElementById('chat-text').focus()}
function addBubble(text,user=false){const p=document.createElement('p');p.className='bubble'+(user?' user':'');p.textContent=text;const m=document.getElementById('messages');m.appendChild(p);m.scrollTop=m.scrollHeight}
document.addEventListener('click',e=>{const b=e.target.closest('[data-chat],[data-product],[data-filter],[data-question],[data-request]');if(b?.hasAttribute('data-chat'))openChat();if(b?.hasAttribute('data-request'))openChat('Bonjour MDS, je souhaite en savoir plus sur : '+b.dataset.request+'.');if(b?.hasAttribute('data-filter')){filter=b.dataset.filter;updateCatalog()}if(b?.hasAttribute('data-product')){const p=products[Number(b.dataset.product)];document.getElementById('detail-body').innerHTML=`<img src="${p.image}" alt="${escape(p.name)}"><div><div class="eyebrow">${labels[categories.indexOf(p.category)]}</div><h2>${escape(p.name)}</h2><p>Un produit de notre sélection MDS. Pour les disponibilités, les quantités et les modalités de livraison, échangez avec notre équipe.</p><button class="btn" id="product-request">Demander sur WhatsApp ↗</button></div>`;document.getElementById('product-request').onclick=()=>{document.getElementById('detail').close();openChat('Bonjour MDS, je suis intéressé(e) par le produit : '+p.name+'. Pouvez-vous me préciser sa disponibilité ?')};document.getElementById('detail').showModal()}
if(b?.hasAttribute('data-question')){const answers={produits:'Découvrez notre catalogue de fruits, légumes, poissons, produits agricoles, viandes et œufs. Vous pouvez ouvrir une fiche produit pour préparer votre demande.',livraison:'MDS propose un service de livraison et de distribution. Indiquez votre quartier et les produits souhaités sur WhatsApp pour confirmer les modalités avec notre équipe.',entreprise:'Nous accompagnons les restaurants, hôtels, entreprises et institutions. Précisez vos produits, quantités et la fréquence d’approvisionnement souhaitée.'};addBubble(answers[b.dataset.question]);setRequest('Bonjour MDS, je souhaite des informations sur '+({produits:'vos produits',livraison:'la livraison',entreprise:'un approvisionnement professionnel'}[b.dataset.question])+'.')}
if(e.target.id==='reset-search'){filter='Tous';search='';document.getElementById('search').value='';updateCatalog()}});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;updateCatalog()}});document.getElementById('menu').onclick=()=>{const nav=document.querySelector('nav');nav.classList.toggle('open');document.getElementById('menu').setAttribute('aria-expanded',String(nav.classList.contains('open')))};document.getElementById('close-chat').onclick=()=>document.getElementById('chat').hidden=true;document.getElementById('close-detail').onclick=()=>document.getElementById('detail').close();document.getElementById('chat-form').onsubmit=e=>{e.preventDefault();const input=document.getElementById('chat-text');const t=input.value.trim();if(!t)return;addBubble(t,true);setRequest('Bonjour MDS, '+t);addBubble('Votre demande est prête. Cliquez sur « Continuer sur WhatsApp » pour l’envoyer à notre équipe.');input.value=''};
document.addEventListener('submit',e=>{if(e.target.id==='contact-form'){e.preventDefault();const f=new FormData(e.target);const t=`Bonjour MDS, je suis ${f.get('name')}.\n${f.get('email')?'Email : '+f.get('email')+'\n':''}${f.get('message')}`;const a=document.createElement('a');a.href=wa+'?text='+encodeURIComponent(t);a.target='_blank';a.rel='noopener';a.click();document.getElementById('contact-status').textContent='Votre demande est préparée. Vérifiez et envoyez votre message dans WhatsApp.'}});window.addEventListener('hashchange',route);fetch('products.json').then(r=>{if(!r.ok)throw Error('catalogue');return r.json()}).then(p=>{products=p;route()}).catch(()=>{main.innerHTML='<div class="container page-head"><h1>Le catalogue est momentanément indisponible.</h1><a class="btn" href="https://wa.me/243834691077">Contacter MDS sur WhatsApp ↗</a></div>'});
